const assert = require('node:assert/strict');
const fs = require('node:fs');
const os = require('node:os');
const path = require('node:path');
const root = '/home/jyarwood/workspace/pi-dish-r2';
require(root + '/test/test-env').applyTestEnv();
const home = fs.mkdtempSync(path.join(os.tmpdir(), 'pi-dish-r2-count-'));
process.env.HOME = home;
const store = require(root + '/lib/routines');
const { createRoutineRunner } = require(root + '/lib/routine-runner');
const { createRoutineHandlers } = require(root + '/lib/routine-handlers');
const originalRead = fs.readFileSync;
const originalStringify = JSON.stringify;
let reads = 0;
let sizes = 0;
let input;
let toJSONCalls = 0;
fs.readFileSync = function(file, ...args) {
  if (String(file).endsWith('/routines.json')) reads++;
  return originalRead.call(this, file, ...args);
};
JSON.stringify = function(value, ...args) {
  if (value === input) sizes++;
  return originalStringify.call(this, value, ...args);
};
const runner = createRoutineRunner({ store, createSession: () => new Promise(() => {}), resumeSession: async () => null,
  getLiveSession: async () => null, closeSession: async () => { throw new Error('unexpected close'); }, composePrompt: () => '', log: { error() {} } });
const handlers = createRoutineHandlers({ runner, validateHarnessPilotSelection: async () => {} });
const definition = name => ({ name, cwd: home, prompt: 'R2 work-count probe' });
const counts = {};
function measure(name, fn) { reads = sizes = 0; const value = fn(); counts[name] = { definitionReads: reads, inputSizes: sizes }; return value; }
(async () => {
  try {
    const first = measure('create', () => store.createRoutine(definition('mutation')));
    measure('markScheduled', () => store.markScheduled(first.id, 60000));
    measure('update', () => store.updateRoutine('MUTATION', { description: 'owned snapshot' }));
    measure('delete', () => store.deleteRoutine(first.id));
    store.createRoutine(definition('route-delete'));
    measure('routeDelete', () => handlers.remove({ params: { id: 'ROUTE-DELETE' } }, { status() { return this; }, json(body) { assert.equal(body.success, true); } }));
    const second = store.createRoutine(definition('admit'));
    input = { toJSON() { toJSONCalls++; return { message: 'one sizing pass', unicode: 'é' }; } };
    reads = sizes = 0;
    let status = 200;
    await handlers.invoke({ params: { id: second.id }, body: { input, source: 'probe' }, query: {} }, {
      status(value) { status = value; return this; }, json(body) {
        assert.equal(body.invocation.input, input);
        JSON.stringify(body); // Response serialization, distinct from sizing/persistence.
      }
    });
    counts.routeAdmission = { definitionReads: reads, inputSizes: sizes, originalToJSONCalls: toJSONCalls };
    assert.equal(status, 202);
    const direct = store.createRoutine(definition('direct-admit'));
    measure('runnerAdmission', () => runner.invoke(direct, { input }));
    measure('ledgerAdmission', () => store.createInvocation({ routine: direct, status: 'completed', input }));
    const disabled = store.createRoutine({ ...definition('disabled'), enabled: false });
    const skipped = measure('disabledSchedule', () => runner.invoke(disabled, { trigger: 'schedule', input }));
    assert.equal(skipped.input, null);
    measure('busySchedule', () => runner.invoke(direct, { trigger: 'schedule', input }));
    const expected = process.argv[2];
    if (expected === 'baseline') {
      assert.equal(counts.update.definitionReads, 2);
      assert.equal(counts.delete.definitionReads, 2);
      assert.equal(counts.routeDelete.definitionReads, 3);
      assert.equal(counts.routeAdmission.inputSizes, 3);
    } else if (expected === 'final') {
      assert.equal(counts.update.definitionReads, 1);
      assert.equal(counts.delete.definitionReads, 1);
      assert.equal(counts.routeDelete.definitionReads, 1);
      assert.equal(counts.routeAdmission.inputSizes, 1);
      assert.equal(counts.routeAdmission.originalToJSONCalls, 3, 'size + initial persistence + response');
      assert.equal(counts.create.definitionReads, 1);
      assert.equal(counts.markScheduled.definitionReads, 1);
      for (const key of ['runnerAdmission', 'ledgerAdmission', 'disabledSchedule', 'busySchedule']) {
        assert.equal(counts[key].inputSizes, 1, key);
      }
    }
    console.log(JSON.stringify({ phase: expected, counts }));
  } finally {
    runner.stop(); fs.readFileSync = originalRead; JSON.stringify = originalStringify;
    fs.rmSync(home, { recursive: true, force: true });
  }
})().catch(error => { console.error(error); process.exitCode = 1; });

const assert = require('node:assert/strict');
const fs = require('node:fs');
const os = require('node:os');
const path = require('node:path');
const root = '/home/jyarwood/workspace/pi-dish-r2';
require(root + '/test/test-env').applyTestEnv();
const home = fs.mkdtempSync(path.join(os.tmpdir(), 'pi-dish-r2-runtime-'));
process.env.HOME = home;
process.env.PI_DISH_HEADLESS = 'rpc';
process.env.PI_DISH_ROUTINE_CLOSE_GRACE_MS = '0';
process.env.PI_DISH_PI_COMMAND = `${process.execPath} ${root}/test/fixtures/fake-rpc-pi.js`;
process.env.PI_FIXTURE_LOG = path.join(home, 'commands.jsonl');
for (const key of Object.keys(process.env)) if (/API_KEY|AUTH_TOKEN|PROVIDER|CREDENTIAL/.test(key)) delete process.env[key];
const server = require(root + '/server');
const store = require(root + '/lib/routines');
const { getAllRPCSessions } = require(root + '/lib/rpc-session');
const { createRoutineRunner } = require(root + '/lib/routine-runner');
const { composeRoutinePrompt } = require(root + '/lib/routine-handlers');
const { once } = require('node:events');
let runner;
let base;
async function request(method, route, body) {
  const response = await fetch(base + route, { method, ...(body === undefined ? {} : { headers: { 'content-type': 'application/json' }, body: JSON.stringify(body) }) });
  return { status: response.status, body: await response.json() };
}
async function waitFor(fn) {
  const end = Date.now() + 20000;
  while (Date.now() < end) { const value = await fn(); if (value) return value; await new Promise(resolve => setTimeout(resolve, 25)); }
  throw new Error('smoke timed out');
}
(async () => {
  try {
    if (!server.listening) await once(server, 'listening');
    base = `http://127.0.0.1:${server.address().port}`;
    const made = await request('POST', '/api/routines', { name: 'r2-admission', cwd: home, prompt: 'R2 admitted input.' });
    assert.equal(made.status, 201);
    const routine = made.body.routine;
    const endpoint = `/api/routines/${routine.id}/invoke`;
    assert.equal((await request('POST', endpoint, { input: 'x'.repeat(40000), source: 42 })).status, 413);
    assert.equal((await request('POST', endpoint, { source: 'bad\nsource' })).status, 400);
    assert.equal(store.countInvocations(routine.id), 0);
    const started = await request('POST', endpoint, { input: { unicode: 'é', task: 'r2' }, source: 'isolated-smoke' });
    assert.equal(started.status, 202);
    const finished = await waitFor(() => { const row = store.getInvocation(started.body.invocation.id); return row?.status === 'completed' && row.closed && row; });
    assert.equal(finished.error, null);
    const commands = fs.readFileSync(process.env.PI_FIXTURE_LOG, 'utf8').trim().split('\n').map(JSON.parse);
    assert.ok(commands.some(command => command.type === 'prompt' && command.message.includes('isolated-smoke') && command.message.includes('"unicode": "é"')));
    assert.equal((await request('DELETE', `/api/routines/${routine.id}`)).body.invocations, 1);
    assert.equal((await request('GET', `/api/routine-invocations/${finished.id}`)).body.invocation.routineName, 'r2-admission');

    const at = new Date(Date.now() + 5 * 60000); at.setSeconds(0, 0);
    const scheduled = store.createRoutine({ name: 'r2-schedule', cwd: home, prompt: 'R2 scheduled invocation.', schedule: { cron: `${at.getMinutes()} ${at.getHours()} * * *` } });
    const ports = { store,
      createSession: async spec => { const result = await request('POST', '/api/sessions/new', spec); assert.equal(result.status, 200, JSON.stringify(result.body)); return result.body.id; },
      resumeSession: async id => { const result = await request('POST', `/api/sessions/${id}/resume`, {}); assert.equal(result.status, 200); return result.body; },
      getLiveSession: async id => getAllRPCSessions().find(session => session.id === id) || null,
      closeSession: id => request('POST', `/api/sessions/${id}/close`, {}),
      composePrompt: (definition, invocation) => composeRoutinePrompt(definition, invocation, { selfHostId: 'isolated', resolveLocal: () => null, fleetNames: () => [] }),
      now: () => at.getTime()
    };
    runner = createRoutineRunner(ports);
    runner.tick(at.getTime());
    const scheduledDone = await waitFor(() => { const row = store.lastInvocation(scheduled.id); return row?.status === 'completed' && row.closed && row; });
    assert.equal(scheduledDone.trigger, 'schedule');
    assert.equal(store.getRoutine(scheduled.id).lastScheduledMinute, at.getTime());
    runner.stop(); runner = createRoutineRunner(ports);
    await runner.recoverAfterRestart();
    runner.tick(at.getTime() + 15000);
    assert.equal(store.countInvocations(scheduled.id), 1);
    const deleted = store.deleteRoutine('R2-SCHEDULE');
    assert.equal(deleted.id, scheduled.id);
    assert.equal(store.getInvocation(scheduledDone.id).routineName, 'r2-schedule');
    console.log(JSON.stringify({ admission: 'real HTTP→runner→RPC prompt→completion→owned close', rejection: '413 before invalid source; 400 framing; no rows', schedule: 'actual runner→HTTP lifecycle coordinator→RPC child; completion and close; recreated runner same-minute suppression', deletion: 'history readable for both runs', home: 'temporary, removed in finally', platform: process.platform, node: process.version }));
  } finally {
    runner?.stop();
    const children = getAllRPCSessions();
    for (const session of children) session.kill();
    await new Promise(resolve => server.close(resolve));
    fs.rmSync(home, { recursive: true, force: true });
  }
})().catch(error => { console.error(error); process.exitCode = 1; });

const assert = require('node:assert/strict');
const fs = require('node:fs');
const os = require('node:os');
const path = require('node:path');
const root = '/home/jyarwood/workspace/pi-dish-r2';
require(root + '/test/test-env').applyTestEnv();
const home = fs.mkdtempSync(path.join(os.tmpdir(), 'pi-dish-r2-boundary-'));
process.env.HOME = home;
try {
  const store = require(root + '/lib/routines');
  const routine = store.createRoutine({ name: 'boundary', cwd: home, prompt: 'private brand' });
  // TypeScript privacy is not a runtime guard: even a direct JS constructor call must measure input.
  const rawConstructed = new store.RoutineInputAdmission({ data: 'x'.repeat(store.MAX_INPUT_BYTES) }, 0);
  assert.equal(store.RoutineInputAdmission.prepare(rawConstructed), null);
  assert.throws(() => store.createInvocation({ routine, status: 'completed', input: rawConstructed }), { status: 413 });
  assert.deepEqual(store.readInvocations(), []);
  const { spawnSync } = require('node:child_process');
  const file = path.join(home, 'admission-negative.ts');
  fs.writeFileSync(file, `import { RoutineInputAdmission } from '${root}/lib/routines';\nnew RoutineInputAdmission({ payload: 'unchecked' });\nconst forged: RoutineInputAdmission = {};\nvoid forged;\n`);
  const checked = spawnSync(process.execPath, [root + '/node_modules/typescript/bin/tsc',
    '--ignoreConfig', '--noEmit', '--strict', '--skipLibCheck', '--target', 'es2022',
    '--module', 'nodenext', '--typeRoots', root + '/node_modules/@types', file], { encoding: 'utf8' });
  assert.notEqual(checked.status, 0, checked.stdout + checked.stderr);
  assert.match(checked.stdout, /TS2673/, 'private constructor rejects unchecked construction');
  assert.match(checked.stdout, /TS2741|TS2739/, 'structural shape cannot forge private slots');
  console.log(JSON.stringify({ runtime: 'direct JS constructor cannot assert arbitrary size; oversized genuine brand rejected; no row', typeNegatives: checked.stdout.trim() }));
} finally { fs.rmSync(home, { recursive: true, force: true }); }
